{
  "$schema": "https://charm.land/crush.json",
  "options": { "disable_metrics": true, "disable_provider_auto_update": true },
  "providers": {
    "{{provider_key}}": {
      "name": "Streamscope",
      "type": "anthropic",
      "base_url": "{{base_url}}",
      "api_key": "{{api_key}}",
      "models": [
{{#each routes}}        {
          "id": "{{model_alias}}",
          "name": "{{model_alias}}"{{#if context_window}},
          "context_window": {{context_window}}{{/if}}{{#if max_output_tokens}},
          "default_max_tokens": {{max_output_tokens}}{{/if}},
          "supports_attachments": {{supports_vision}},
          "can_reason": {{supports_reasoning}}
        }{{#unless @last}},{{/unless}}
{{/each}}      ]
    }
  },
  "models": {
    "large": { "model": "{{model_slot_default}}", "provider": "{{provider_key}}" },
    "small": { "model": "{{model_slot_fast}}", "provider": "{{provider_key}}" }
  }{{#if mcp_servers}},
  "mcp": {
{{#each mcp_servers}}    "{{slug}}": {
      "type": "http",
      "url": "{{url}}",
      "headers": { "Authorization": "Bearer {{api_key}}" }
    }{{#unless @last}},{{/unless}}
{{/each}}  }{{/if}}
}

